import random

def getMonthlySales():
    return random.randint(0, 100000)

def main():
    total_sales = 0
    quarterly_sales = [0, 0, 0, 0]  # Q1, Q2, Q3, Q4

    for month in range(1, 13):
        sales = getMonthlySales()
        total_sales += sales
        quarter_index = (month - 1) // 3
        quarterly_sales[quarter_index] += sales

    print("Quarterly Sales:")
    for i, sales in enumerate(quarterly_sales, 1):
        print(f"Quarter {i}: ${sales}")

if __name__ == "__main__":
    main()

