import random

def getMonthlySales():
    return random.randint(0, 100000)

def main():
    monthly_sales = []
    for month in range(12):
        sales = getMonthlySales()
        monthly_sales.append(sales)

    # Calculate quarterly sales
    for quarter in range(4):
        start_month = quarter * 3
        end_month = start_month + 3
        quarterly_total = sum(monthly_sales[start_month:end_month])
        print(f"Quarter {quarter + 1} sales: {quarterly_total}")

    # Calculate annual total
    annual_total = sum(monthly_sales)
    print(f"Annual sales: {annual_total}")

if __name__ == "__main__":
    main()
